package in.gov.nic.apar.service;

import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.jdbc.core.namedparam.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.time.*; import com.fasterxml.jackson.databind.ObjectMapper;
@Service public class AparService {
 private final JdbcTemplate db; private final NamedParameterJdbcTemplate named; private final PasswordEncoder encoder; private final CurrentUser current; private final in.gov.nic.apar.security.JwtService jwt; private final ObjectMapper json=new ObjectMapper();
 public AparService(JdbcTemplate db,PasswordEncoder e,CurrentUser c,in.gov.nic.apar.security.JwtService j){this.db=db;this.named=new NamedParameterJdbcTemplate(db);this.encoder=e;this.current=c;this.jwt=j;}
 public Map<String,Object> login(String email,String password){var rows=db.queryForList("select u.id,u.email,u.password_hash,u.role,u.enabled,e.id employee_id,e.active from tran.user_account u left join tran.employee_details e on e.id=u.employee_id where lower(u.email)=lower(?)",email); if(rows.isEmpty()) throw new IllegalArgumentException("Invalid email or password"); var r=rows.get(0); if(!Boolean.TRUE.equals(r.get("enabled")) || ("EMPLOYEE".equals(r.get("role"))&&!Boolean.TRUE.equals(r.get("active"))) || !encoder.matches(password,(String)r.get("password_hash"))) throw new IllegalArgumentException("Invalid email or password, or account inactive"); return Map.of("token",token(email,(String)r.get("role"),((Number)r.get("id")).longValue()),"role",r.get("role"),"email",email,"employeeId",r.get("employee_id")==null?0:r.get("employee_id")); }
 private String token(String e,String role,long id){return jwt.issue(e,role,id);}
 @Transactional public Map<String,Object> register(Map<String,Object> b){String email=s(b,"email").toLowerCase(); Long dept=id(b.get("departmentId")); String code=s(b,"employeeCode").isBlank()?"REG-"+UUID.randomUUID().toString().substring(0,8).toUpperCase():s(b,"employeeCode"); Long id=db.queryForObject("insert into tran.employee_details(employee_code,first_name,middle_name,last_name,gender,date_of_birth,department_id,designation,mobile,email,active) values(?,?,?,?,?,nullif(?,'')::date,?,?,?, ?,false) returning id",Long.class,code,s(b,"firstName"),s(b,"middleName"),s(b,"lastName"),s(b,"gender"),s(b,"dateOfBirth"),dept,s(b,"designation"),s(b,"mobile"),email); db.update("insert into tran.user_account(employee_id,email,password_hash,role,enabled) values(?,?,?,'EMPLOYEE',true)",id,email,encoder.encode(s(b,"password"))); return Map.of("id",id,"message","Registration received. An authority must activate your account before login."); }
 public List<Map<String,Object>> departments(){return db.queryForList("select id,name,code from tran.department order by name");}
 public List<Map<String,Object>> employees(String q,String department,String active){String sql="select e.id,e.employee_code as \"employeeCode\",e.first_name as \"firstName\",e.middle_name as \"middleName\",e.last_name as \"lastName\",e.email,e.mobile,e.designation,e.active,d.name as \"department\" from tran.employee_details e left join tran.department d on d.id=e.department_id where (?='' or lower(concat_ws(' ',e.first_name,e.middle_name,e.last_name,e.employee_code,e.email,e.designation)) like lower('%'||?||'%')) and (?='' or d.id::text=?) and (?='' or e.active::text=?) order by e.id desc";return db.queryForList(sql,n(q),n(q),n(department),n(department),n(active),n(active));}
 @Transactional public Map<String,Object> addEmployee(Map<String,Object>b){String email=s(b,"email").toLowerCase(); String code=s(b,"employeeCode").isBlank()?"EMP-"+UUID.randomUUID().toString().substring(0,8).toUpperCase():s(b,"employeeCode"); Long id=db.queryForObject("insert into tran.employee_details(employee_code,first_name,middle_name,last_name,gender,date_of_birth,department_id,designation,mobile,email,active) values(?,?,?,?,?,nullif(?,'')::date,?,?,?, ?,true) returning id",Long.class,code,s(b,"firstName"),s(b,"middleName"),s(b,"lastName"),s(b,"gender"),s(b,"dateOfBirth"),id(b.get("departmentId")),s(b,"designation"),s(b,"mobile"),email); db.update("insert into tran.user_account(employee_id,email,password_hash,role,enabled) values(?,?,?,'EMPLOYEE',true)",id,email,encoder.encode(s(b,"password").isBlank()?"ChangeMe@123":s(b,"password")));return Map.of("id",id);}
 @Transactional public void updateEmployee(long id,Map<String,Object>b){db.update("update tran.employee_details set first_name=?,middle_name=?,last_name=?,department_id=?,designation=?,mobile=?,email=?,updated_at=now() where id=?",s(b,"firstName"),s(b,"middleName"),s(b,"lastName"),id(b.get("departmentId")),s(b,"designation"),s(b,"mobile"),s(b,"email"),id); db.update("update tran.user_account set email=? where employee_id=?",s(b,"email"),id);}
 @Transactional public void active(long id,boolean active){if(idOfCurrentEmployee()==id)throw new IllegalArgumentException("You cannot deactivate your own account");db.update("update tran.employee_details set active=? where id=?",active,id);db.update("update tran.user_account set enabled=? where employee_id=?",active,id);}
 private long idOfCurrentEmployee(){var l=db.queryForList("select id from tran.employee_details where lower(email)=lower(?)",current.email());return l.isEmpty()?-1:((Number)l.get(0).get("id")).longValue();}
 @Transactional public void deleteEmployee(long id){if(idOfCurrentEmployee()==id)throw new IllegalArgumentException("You cannot delete your own account");Integer count=db.queryForObject("select count(*) from tran.employee_acr_status where employee_id=?",Integer.class,id);if(count!=null&&count>0){active(id,false);return;}db.update("delete from tran.employee_details where id=?",id);}
 public Map<String,Object> cycle(){var l=db.queryForList("select id,assessment_year as \"assessmentYear\",due_date as \"dueDate\",is_open as \"open\" from tran.acr_cycle order by id desc limit 1");return l.isEmpty()?Map.of():l.get(0);}
 @Transactional public void setCycle(Map<String,Object>b){db.update("update tran.acr_cycle set is_open=false");db.update("insert into tran.acr_cycle(assessment_year,due_date,is_open) values(?,?,?) on conflict(assessment_year) do update set due_date=excluded.due_date,is_open=excluded.is_open",s(b,"assessmentYear"),java.sql.Date.valueOf(s(b,"dueDate")),Boolean.parseBoolean(s(b,"open")));}
 @Transactional public void requestApar(List<Long> ids,String message){var c=cycle();if(c.isEmpty())throw new IllegalArgumentException("Create an assessment cycle first");long cycleId=((Number)c.get("id")).longValue();String year=s(c,"assessmentYear");for(long id:ids){var existing=db.queryForList("select id,status from tran.employee_acr_status where employee_id=? and assessment_year=?",id,year);long acr;if(existing.isEmpty())acr=db.queryForObject("insert into tran.employee_acr_status(employee_id,cycle_id,assessment_year,requested,requested_at,status) values(?,?,?,true,now(),'PENDING') returning id",Long.class,id,cycleId,year);else{acr=((Number)existing.get(0).get("id")).longValue();String status=s(existing.get(0),"status");if(Set.of("APPROVED","REJECTED").contains(status))throw new IllegalArgumentException("Annual report already completed; a new request requires a new assessment year");db.update("update tran.employee_acr_status set requested=true,requested_at=now(),status=case when status='NEEDS_RESUBMISSION' then status else 'PENDING' end where id=?",acr);} notify(id,"APAR_REQUEST","APAR submission requested",message);audit(acr,"APAR_REQUESTED",Map.of("message",message));}}
 @Transactional public void submit(long employeeId,List<Map<String,Object>> rows){var c=cycle();if(c.isEmpty()||!Boolean.TRUE.equals(c.get("open")))throw new IllegalArgumentException("No open assessment cycle");var st=db.queryForList("select s.* from tran.employee_acr_status s where s.employee_id=? and s.assessment_year=?",employeeId,s(c,"assessmentYear"));if(st.isEmpty()||!Boolean.TRUE.equals(st.get(0).get("requested")))throw new IllegalArgumentException("The authority has not requested your APAR");long id=((Number)st.get(0).get("id")).longValue();String status=s(st.get(0),"status");if(!Set.of("PENDING","NEEDS_RESUBMISSION").contains(status))throw new IllegalArgumentException("This annual APAR is not open for submission");if(LocalDate.now().isAfter(LocalDate.parse(s(c,"dueDate").substring(0,10))))throw new IllegalArgumentException("Submission deadline has passed");db.update("delete from tran.employee_acr_details where acr_status_id=?",id);int seq=0;for(var row:rows)db.update("insert into tran.employee_acr_details(acr_status_id,target,achievement,sequence_no) values(?,?,?,?)",id,s(row,"target"),s(row,"achievement"),++seq);int rev=((Number)st.get(0).get("revision")).intValue()+1;db.update("update tran.employee_acr_status set submitted=true,status='SUBMITTED',revision=?,submitted_at=now(),resubmission_reason=null where id=?",rev,id);var snap=Map.of("assessmentYear",s(c,"assessmentYear"),"revision",rev,"entries",rows);db.update("insert into tran.acr_submission_history(acr_status_id,revision,snapshot,submitted_by) values(?,?,?::jsonb,?)",id,rev,toJson(snap),userId());audit(id,"SUBMITTED",Map.of("revision",rev));}
 public List<Map<String,Object>> acrList(){if(current.authority())return db.queryForList("select s.id,s.assessment_year as \"assessmentYear\",s.status,s.grade,s.flagged,s.revision,e.employee_code as \"employeeCode\",concat_ws(' ',e.first_name,e.last_name) as \"employee\",d.name as \"department\" from tran.employee_acr_status s join tran.employee_details e on e.id=s.employee_id left join tran.department d on d.id=e.department_id order by s.id desc");return db.queryForList("select s.id,s.assessment_year as \"assessmentYear\",s.status,s.grade,s.flagged,s.revision from tran.employee_acr_status s join tran.employee_details e on e.id=s.employee_id where lower(e.email)=lower(?) order by s.id desc",current.email());}
 public Map<String,Object> acr(long id){var r=db.queryForList("select s.*,e.first_name,e.last_name,e.employee_code from tran.employee_acr_status s join tran.employee_details e on e.id=s.employee_id where s.id=?",id);if(r.isEmpty())throw new IllegalArgumentException("APAR not found");if(!current.authority()&&!Objects.equals(((Number)r.get(0).get("employee_id")).longValue(),idOfCurrentEmployee()))throw new SecurityException("Forbidden");var out=new HashMap<String,Object>(r.get(0));out.put("entries",db.queryForList("select target,achievement,sequence_no from tran.employee_acr_details where acr_status_id=? order by sequence_no",id));return out;}
 @Transactional public void review(long id,Map<String,Object>b){if(!current.authority())throw new SecurityException("Authority only");db.update("update tran.employee_acr_status set status=?,grade=?,remark=?,flagged=?,reviewed_at=now() where id=? and status='SUBMITTED'",s(b,"decision"),s(b,"grade"),s(b,"remark"),Boolean.parseBoolean(s(b,"flagged")),id);var r= db.queryForMap("select employee_id,status from tran.employee_acr_status where id=?",id);notify(((Number)r.get("employee_id")).longValue(),"APAR_REVIEW","APAR reviewed","Your APAR status is "+r.get("status")+". "+s(b,"remark"));audit(id,"REVIEWED",b);}
 @Transactional public void returnForRevision(long id,String reason){if(!current.authority()||reason.isBlank())throw new IllegalArgumentException("Authority and a resubmission reason are required");db.update("update tran.employee_acr_status set status='NEEDS_RESUBMISSION',resubmission_reason=?,reviewed_at=now() where id=? and status='SUBMITTED'",reason,id);long emp=db.queryForObject("select employee_id from tran.employee_acr_status where id=?",Long.class,id);notify(emp,"APAR_RESUBMISSION","APAR revision required",reason);audit(id,"RESUBMISSION_REQUESTED",Map.of("reason",reason));}
 public List<Map<String,Object>> notifications(){return db.queryForList("select n.id,n.type,n.title,n.message,n.read,n.created_at as \"createdAt\" from tran.notification n join tran.employee_details e on e.id=n.recipient_employee_id where lower(e.email)=lower(?) order by n.created_at desc",current.email());}
 public int unread(){return db.queryForObject("select count(*) from tran.notification n join tran.employee_details e on e.id=n.recipient_employee_id where lower(e.email)=lower(?) and n.read=false",Integer.class,current.email());}
 public void read(long id){db.update("update tran.notification n set read=true from tran.employee_details e where n.recipient_employee_id=e.id and lower(e.email)=lower(?) and n.id=?",current.email(),id);} public void readAll(){db.update("update tran.notification n set read=true from tran.employee_details e where n.recipient_employee_id=e.id and lower(e.email)=lower(?)",current.email());}
 @Transactional public void sendNotification(Map<String,Object>b){if(!current.authority())throw new SecurityException("Authority only");String mode=s(b,"mode");List<Long> ids;if(mode.equals("ALL"))ids=db.queryForList("select id from tran.employee_details where active=true",Long.class);else if(mode.equals("DEPARTMENT"))ids=db.queryForList("select id from tran.employee_details where active=true and department_id=?",Long.class,id(b.get("departmentId")));else{Object raw=b.get("employeeIds");ids=raw instanceof List<?> l?l.stream().map(x->((Number)x).longValue()).toList():List.of();}for(long id:ids)notify(id,"CUSTOM",s(b,"title"),s(b,"message"));}
 public List<Map<String,Object>> history(long id){assertOwnerOrAuthority(id);return db.queryForList("select revision,snapshot,created_at as \"createdAt\" from tran.acr_submission_history where acr_status_id=? order by revision",id);} public List<Map<String,Object>> audit(long id){assertOwnerOrAuthority(id);return db.queryForList("select action,details,created_at as \"createdAt\" from tran.acr_audit where acr_status_id=? order by id",id);} private void assertOwnerOrAuthority(long id){if(current.authority())return;Long owner=db.queryForObject("select employee_id from tran.employee_acr_status where id=?",Long.class,id);if(owner==null||owner!=idOfCurrentEmployee())throw new SecurityException("Forbidden");}
 private void notify(long emp,String type,String title,String msg){db.update("insert into tran.notification(recipient_employee_id,type,title,message) values(?,?,?,?)",emp,type,title,msg);} private void audit(long acr,String action,Object details){db.update("insert into tran.acr_audit(acr_status_id,actor_user_id,action,details) values(?,?,?,?::jsonb)",acr,userId(),action,toJson(details));} private long userId(){return db.queryForObject("select id from tran.user_account where lower(email)=lower(?)",Long.class,current.email());} private String toJson(Object x){try{return json.writeValueAsString(x);}catch(Exception e){return "{}";}} private static String s(Map<?,?>m,String k){Object v=m.get(k);return v==null?"":String.valueOf(v);} private static String n(Object x){return x==null?"":String.valueOf(x);} private static Long id(Object x){return x==null||String.valueOf(x).isBlank()?null:Long.valueOf(String.valueOf(x));}
}
